def _lattice_points(s, theta):
    """26 sites of a triangular lattice with basis s*(cos th, sin th) and
    s*(cos(th+60deg), sin(th+60deg)) centered at (0.5,0.5); keep sites inside
    [0.04,0.96]^2, taking the 26 closest to the square center."""
    u = s * np.array([np.cos(theta), np.sin(theta)])
    v = s * np.array([np.cos(theta + np.pi / 3.0), np.sin(theta + np.pi / 3.0)])
    pts = []
    for i in range(-4, 5):
        for j in range(-4, 5):
            p = np.array([0.5, 0.5]) + i * u + j * v
            if 0.04 <= p[0] <= 0.96 and 0.04 <= p[1] <= 0.96:
                pts.append(p)
    if len(pts) < _N:
        return None
    pts = np.array(pts, dtype=float)
    d = np.linalg.norm(pts - 0.5, axis=1)
    return pts[np.argsort(d)[:_N]].copy()


def _greedy_radii_for(C):
    """Wall-then-pairwise greedy maximal radii for fixed centers C."""
    r = np.minimum(np.min(np.column_stack([C, 1.0 - C]), axis=1), 0.5)
    for i in range(_N):
        for j in range(i + 1, _N):
            d = np.linalg.norm(C[i] - C[j])
            if r[i] + r[j] > d and d > 1e-12:
                sc = d / (r[i] + r[j])
                r[i] *= sc
                r[j] *= sc
    return np.maximum(r, 1e-4)


def _opt_lattice(starts):
    """Shared Nelder-Mead driver: optimize (s, theta) over the given
    deterministic starts (bounded count, maxiter 200 each) on the
    greedy-maximal-radii sum of the resulting 26-point lattice."""
    def neg(p):
        s, th = p
        if not (0.08 <= s <= 0.30):
            return 10.0
        C = _lattice_points(s, th)
        if C is None:
            return 10.0
        return -float(np.sum(_greedy_radii_for(C.copy())))

    best_p, best_v = None, np.inf
    for s0, th0 in starts:
        try:
            res = minimize(neg, np.array([s0, th0], dtype=float),
                           method="Nelder-Mead",
                           options={"maxiter": 200, "xatol": 1e-6, "fatol": 1e-10})
            if res.fun < best_v:
                best_v, best_p = float(res.fun), res.x
        except Exception:
            continue
    if best_p is None:
        best_p = np.array([0.2, 0.0])
    return float(np.clip(best_p[0], 0.08, 0.30)), float(best_p[1])


def _hex_seed():
    """
    Rotated-lattice seed (replaces the axis-aligned [4,5,4,5,4,5] hex rows):
    a triangular lattice is parameterized by spacing s and rotation theta;
    which 26 sites survive clipping depends on both, so rotating changes the
    wall-contact and defect topology. (s, theta) is optimized by Nelder-Mead
    (<=12 deterministic starts, maxiter 200 each on 2 variables) directly on
    the greedy-maximal-radii sum. Returns (centers, radii).
    """
    starts = [
        (0.20, 0.0), (0.19, np.pi / 12), (0.18, np.pi / 6), (0.21, np.pi / 8),
        (0.17, np.pi / 4), (0.22, np.pi / 10), (0.16, np.pi / 5),
        (0.20, np.pi / 16), (0.185, -np.pi / 12), (0.195, np.pi / 9),
        (0.175, -np.pi / 6), (0.205, np.pi / 14),
    ]
    s, th = _opt_lattice(starts[:12])
    C = _lattice_points(s, th)
    if C is None:
        C = _lattice_points(0.2, 0.0)
    return C, _greedy_radii_for(C.copy())


def _hex_variants():
    """Neighbour layouts of the optimized rotated lattice: theta +/-5 deg and
    spacing +/-3%. Returns a list of (centers, radii) tuples."""
    s0, th0 = _opt_lattice([(0.20, 0.0), (0.18, np.pi / 6), (0.19, np.pi / 12)])
    out = []
    for ds, dth in ((0.0, np.pi / 36), (0.0, -np.pi / 36),
                    (0.03 * s0, 0.0), (-0.03 * s0, 0.0)):
        C = _lattice_points(s0 + ds, th0 + dth)
        if C is not None:
            out.append((C.copy(), _greedy_radii_for(C.copy())))
    return out
